(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04-t*0.5)*6+Math.cos((y+w1y)*0.03+t*0.4)*5;
  const w2y = Math.cos((y+w1y)*0.04+t*0.45)*6+Math.sin((x+w1x)*0.035-t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.6],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.5],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.7],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.4],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.65],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.55],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.055,2.8,0.5],
    [400+Math.cos(t*0.38+2)*60,200+Math.sin(t*0.48+4)*40,0.13,1.4,0.45]
  ];
  let aS=0,iS=0,fS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    fS+=Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.3;
  }
  const act=aS/3.85,inh=iS/3.85,fin=fS/3.85;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.2;
  const turb=Math.sin(sx*0.1+Math.sin(sy*0.08+t)*2+t*0.7)*Math.cos(sy*0.09+Math.cos(sx*0.07-t)*2-t*0.6);
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((fin-act*0.4+inh*0.3+turb*0.5)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend=r1*0.45+r2*0.25+cell*0.2+micro, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,85,120],[30,135,130],[140,170,90],
    [210,175,60],[220,130,65],[195,75,75],[140,40,80],[85,22,65],[30,12,48],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const edge=Math.abs(r1)>0.65?1.2:Math.abs(r2)>0.5?1.1:1.0;
  const glow=Math.max(0,r1*0.8+r2*0.5)*0.15;
  const lum=0.85+Math.sin(r1*Math.PI)*0.15+glow;
  const hueShift=Math.sin(t*0.15)*0.03;
  const sh=f+hueShift;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sh)*lum*edge))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sh)*lum*edge))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sh)*lum*edge))|0
  ];
}
